import React from 'react';
import { StyleSheet, View, Text, TouchableOpacity, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const ShiftCard = ({ shift }) => {
  const renderEmployees = () => {
    const visibleEmployees = shift.employees.slice(0, 3);
    const remainingCount = shift.additionalCount;

    return (
      <View style={styles.employeesContainer}>
        <View style={styles.employeeAvatars}>
          {visibleEmployees.map((employee, index) => (
            <Image
              key={employee.id}
              source={{ uri: employee.avatar }}
              style={[
                styles.employeeAvatar,
                { marginLeft: index > 0 ? -8 : 0 }
              ]}
            />
          ))}
          {remainingCount > 0 && (
            <View style={[styles.additionalCount, { marginLeft: -8 }]}>
              <Text style={styles.additionalCountText}>+{remainingCount}</Text>
            </View>
          )}
        </View>
      </View>
    );
  };

  return (
    <TouchableOpacity style={[styles.card, { backgroundColor: shift.backgroundColor }]}>
      <View style={styles.cardContent}>
        {/* Left side - Icon and Info */}
        <View style={styles.leftSection}>
          <View style={[styles.iconContainer, { backgroundColor: shift.iconColor }]}>
            <Ionicons 
              name={shift.iconName} 
              size={24} 
              color="#FFFFFF" 
            />
          </View>
          
          <View style={styles.infoContainer}>
            <Text style={styles.shiftTitle}>{shift.title}</Text>
            {renderEmployees()}
          </View>
        </View>

        {/* Right side - Time and Status */}
        <View style={styles.rightSection}>
          <View style={[styles.timeTag, { backgroundColor: shift.timeTagColor }]}>
            <Text style={styles.timeText}>{shift.time}</Text>
          </View>
          
          <View style={styles.statusContainer}>
            <Ionicons 
              name={shift.status.icon} 
              size={16} 
              color={shift.status.color} 
            />
            <Text style={[styles.statusText, { color: shift.status.color }]}>
              {shift.status.text}
            </Text>
          </View>
        </View>
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  card: {
    borderRadius: 16,
    marginBottom: 16,
    padding: 16,
    shadowColor: '#000',
    shadowOffset: {
      width: 0,
      height: 2,
    },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  cardContent: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
  },
  leftSection: {
    flexDirection: 'row',
    flex: 1,
    alignItems: 'flex-start',
  },
  iconContainer: {
    width: 40,
    height: 40,
    borderRadius: 20,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 12,
  },
  infoContainer: {
    flex: 1,
  },
  shiftTitle: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#333333',
    marginBottom: 8,
  },
  employeesContainer: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  employeeAvatars: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  employeeAvatar: {
    width: 32,
    height: 32,
    borderRadius: 16,
    borderWidth: 2,
    borderColor: '#FFFFFF',
  },
  additionalCount: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: '#CCCCCC',
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 2,
    borderColor: '#FFFFFF',
  },
  additionalCountText: {
    fontSize: 12,
    fontWeight: 'bold',
    color: '#666666',
  },
  rightSection: {
    alignItems: 'flex-end',
  },
  timeTag: {
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 12,
    marginBottom: 8,
  },
  timeText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#FFFFFF',
  },
  statusContainer: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  statusText: {
    fontSize: 14,
    fontWeight: '500',
    marginLeft: 4,
  },
});

export default ShiftCard;
